def forward(groups):
    total = int(groups[0]) + int(groups[1]) + int(groups[2])
    return {'stored': [total], 'layout': [int(groups[0]), int(groups[1]), int(groups[2])]}

def inverse(record):
    return f"bufstart = {record['layout'][0]}; bufend = {record['layout'][1]}; bufvoid = {record['layout'][2]}"
